 // touch stick, camera drag, and action buttons
 const stick=document.getElementById('stick'),knob=document.getElementById('knob');let stickId=null,stickRect;stick.addEventListener('pointerdown',e=>{e.preventDefault();stickId=e.pointerId;stick.setPointerCapture(stickId);stickRect=stick.getBoundingClientRect();stickMove(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)stickMove(e)});function stickMove(e){let dx=e.clientX-(stickRect.left+stickRect.width/2),dy=e.clientY-(stickRect.top+stickRect.height/2),len=Math.hypot(dx,dy),max=38;if(len>max){dx*=max/len;dy*=max/len}knob.style.transform=`translate(${dx}px,${dy}px)`;moveX=dx/max;moveY=dy/max}function stopStick(e){if(e.pointerId===stickId){stickId=null;moveX=moveY=0;knob.style.transform=''}}stick.addEventListener('pointerup',stopStick);stick.addEventListener('pointercancel',stopStick);
 let touchLookId=null,tx=0,ty=0;renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'&&e.clientX>innerWidth*.3){touchLookId=e.pointerId;tx=e.clientX;ty=e.clientY;renderer.domElement.setPointerCapture(e.pointerId)}});renderer.domElement.addEventListener('pointermove',e=>{if(e.pointerId===touchLookId){yaw-=(e.clientX-tx)*.006;pitch=THREE.MathUtils.clamp(pitch-(e.clientY-ty)*.004,-.72,.38);tx=e.clientX;ty=e.clientY}});renderer.domElement.addEventListener('pointerup',e=>{if(e.pointerId===touchLookId)touchLookId=null});const fireBtn=document.getElementById('fire');fireBtn.addEventListener('pointerdown',e=>{e.preventDefault();fireHeld=true;shoot()});['pointerup','pointercancel','pointerleave'].forEach(ev=>fireBtn.addEventListener(ev,()=>fireHeld=false));document.getElementById('reload').addEventListener('pointerdown',e=>{e.preventDefault();reload()});document.getElementById('jump').addEventListener('pointerdown',e=>{e.preventDefault();if(onGround){velocityY=7;onGround=false}});
 let prev=performance.now();function animate(now){requestAnimationFrame(animate);const dt=Math.min(.04,(now-prev)/1000);prev=now;elapsed+=dt;if(active){shotCooldown=Math.max(0,shotCooldown-dt);if(fireHeld&&shotCooldown<=0)shoot();movePlayer(dt);cameraUpdate(dt);if(elapsed>0){for(const b of bots){if(!b.alive)continue;b.cool-=dt;let toward=player.position.clone().sub(b.g.position);toward.y=0;let d=toward.length();if(d>8){toward.normalize();b.g.position.addScaledVector(toward,dt*b.speed);b.g.rotation.y=Math.atan2(-toward.x,-toward.z)}else if(b.cool<=0){b.cool=1.5+rand()*1.4;let damage=4+rand()*5;if(armor>0){let a=Math.min(armor,damage*.65);armor-=a;damage-=a}hp=Math.max(0,hp-damage);document.getElementById('damage').classList.add('hit');setTimeout(()=>document.getElementById('damage').classList.remove('hit'),100);updateHud();if(hp<=0)finish(false)}}}
-let sec=Math.max(0,300-Math.floor(elapsed));document.getElementById('timer').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');zone=Math.max(.38,1-elapsed/380);document.getElementById('zoneBar').style.width=(zone*100)+'%';if(sec===0)finish(bots.filter(b=>b.alive).length===0);}
+let sec=Math.max(0,300-Math.floor(elapsed));document.getElementById('timer').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');zone=Math.max(.38,1-elapsed/380);zoneRing.scale.setScalar(zone*72);document.getElementById('zoneBar').style.width=(zone*100)+'%';const outside=player.position.length()>zone*72;if(outside){hp=Math.max(0,hp-7*dt);document.getElementById('zoneText').textContent='MOVE IN';document.getElementById('zoneText').style.color='#ff8d72';updateHud();if(hp<=0)finish(false)}else{document.getElementById('zoneText').textContent='STABLE';document.getElementById('zoneText').style.color=''}if(sec===0)finish(bots.filter(b=>b.alive).length===0);}
 else cameraUpdate(dt);renderer.render(scene,camera)}requestAnimationFrame(animate);
 addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
 </script>
 </body></html>
